INSERT INTO phrases (phrase_id,lesson_id,english_text,vietnamese_meaning,ipa_phonetic,audio_sample_url,context_note) VALUES
(10121,101,'May I check the name of the person you are meeting?','Tôi kiểm tra tên người bạn sẽ gặp nhé?','/meɪ aɪ ʧɛk ðə neɪm əv ðə ˈpərsən ju ər ˈmitɪŋ/','','PRACTICE_SENTENCE'),
(10122,101,'I am meeting the sales manager this afternoon.','Chiều nay tôi gặp trưởng phòng kinh doanh.','/aɪ æm ˈmitɪŋ ðə seɪlz ˈmænɪʤər ðɪs ˌæftərˈnun/','','PRACTICE_SENTENCE'),
(10123,101,'Would you prefer to wait in the lounge?','Bạn muốn chờ ở khu tiếp khách không?','/wʊd ju prɪˈfər tɪ weɪt ɪn ðə laʊnʤ/','','PRACTICE_SENTENCE'),
(10124,101,'The lounge is just past the reception desk.','Khu tiếp khách nằm ngay sau quầy lễ tân.','/ðə laʊnʤ ɪz ʤɪst pæst ðə rɪˈsɛpʃən dɛsk/','','PRACTICE_SENTENCE'),
(10125,101,'Could we write down the details we have agreed on?','Chúng ta ghi lại chi tiết đã thống nhất nhé?','/kʊd wi raɪt daʊn ðə ˈditeɪlz wi hæv əˈgrid ɔn/','','PRACTICE_SENTENCE'),
(10126,101,'A written summary will help us avoid misunderstandings.','Bản tóm tắt sẽ giúp tránh hiểu nhầm.','/ə ˈrɪtən ˈsəməri wɪl hɛlp ˈjuˈɛs əˈvɔɪd ˌmɪsəndərˈstændɪŋz/','','PRACTICE_SENTENCE'),
(10127,101,'Who should I contact if I have a further question later?','Sau này có thêm câu hỏi tôi nên liên hệ ai?','/hu ʃʊd aɪ ˈkɑnˌtækt ɪf aɪ hæv ə ˈfərðər kˈwɛʃən ˈleɪtər/','','PRACTICE_SENTENCE'),
(10128,101,'We can include the correct contact details in your confirmation.','Chúng tôi có thể ghi thông tin liên hệ đúng trong xác nhận.','/wi kən ˌɪnˈklud ðə kərˈɛkt ˈkɑnˌtækt ˈditeɪlz ɪn jʊr ˌkɑnfərˈmeɪʃən/','','PRACTICE_SENTENCE'),
(10129,101,'Is there anything in this arrangement that you would like clarified?','Có điều gì trong thỏa thuận này bạn muốn làm rõ không?','/ɪz ðɛr ˈɛniˌθɪŋ ɪn ðɪs ərˈeɪnʤmənt ðət ju wʊd laɪk ˈklɛrəˌfaɪd/','','PRACTICE_SENTENCE'),
(10130,101,'I would like to review the details once more before deciding.','Tôi muốn xem lại chi tiết một lần nữa trước khi quyết định.','/aɪ wʊd laɪk tɪ ˌrivˈju ðə ˈditeɪlz wəns mɔr ˌbiˈfɔr ˌdɪˈsaɪdɪŋ/','','PRACTICE_SENTENCE'),
(10221,102,'Which requirement is essential to your team?','Yêu cầu nào thiết yếu với nhóm của bạn?','/wɪʧ rɪkˈwaɪrmənt ɪz ɛˈsɛnʃəl tɪ jʊr tim/','','PRACTICE_SENTENCE'),
(10222,102,'Our team needs a service that is easy to use.','Nhóm chúng tôi cần dịch vụ dễ sử dụng.','/ɑr tim nidz ə ˈsərvɪs ðət ɪz ˈizi tɪ juz/','','PRACTICE_SENTENCE'),
(10223,102,'How many people will use the service?','Có bao nhiêu người sẽ sử dụng dịch vụ?','/haʊ ˈmɛni ˈpipəl wɪl juz ðə ˈsərvɪs/','','PRACTICE_SENTENCE'),
(10224,102,'About ten colleagues will use it regularly.','Khoảng mười đồng nghiệp sẽ sử dụng thường xuyên.','/əˈbaʊt tɛn ˈkɑligz wɪl juz ɪt ˈrɛgjələrli/','','PRACTICE_SENTENCE'),
